function _regLang(code, d) {
  const out = {};
  const cleanStr = (s) => String(s || '').replace(/\s*\r?\n\s*/g, ' ').trim();
  const mapGrp = (keys, str) => {
    if (!str) return;
    const arr = cleanStr(str).split('|');
    keys.forEach((k, i) => {
      if (arr[i] !== undefined && arr[i] !== '') out[k] = arr[i].trim();
    });
  };
  mapGrp(_G1, d.g1);
  mapGrp(_G2, d.g2);
  mapGrp(_G3, d.g3);
  mapGrp(_G4, d.g4);
  mapGrp(_G5, d.g5);
  mapGrp(_G6, d.g6);
  mapGrp(_G7, d.g7);
  out.acvpu = cleanStr(d.acvpu).split('|').map(s => s.trim());
  out.phrases = cleanStr(d.phrases).split('|').map(s => s.trim());
  out.tasks = cleanStr(d.tasks).split('|').map(s => s.trim());
  out.admits = cleanStr(d.admits).split('|').map(s => s.trim());
  out.drSites = cleanStr(d.drSites).split('|').map(s => s.trim());
  window.CDU_LANGS[code] = out;
}

